+fn github_check_state(status: &str, conclusion: &str) -> String {
+    match status.trim().to_ascii_uppercase().as_str() {
+        "QUEUED" | "IN_PROGRESS" | "PENDING" | "WAITING" | "REQUESTED" => {
+            return "pending".into();
+        }
+        "COMPLETED" | "" => return github_check_conclusion_state(conclusion),
+        _ => {}
+    }
+    "unknown".into()
